def transform(grid):
    h, w = len(grid), len(grid[0])
    divider = next(r for r, row in enumerate(grid) if all(v == 5 for v in row))
    out_h = h - divider - 1

    def components(color, r0, r1):
        remaining = {(r, c) for r in range(r0, r1) for c in range(w)
                     if grid[r][c] == color}
        result = []
        while remaining:
            start = remaining.pop()
            comp = {start}
            stack = [start]
            while stack:
                r, c = stack.pop()
                for nr, nc in ((r-1, c), (r+1, c), (r, c-1), (r, c+1)):
                    if (nr, nc) in remaining:
                        remaining.remove((nr, nc))
                        comp.add((nr, nc))
                        stack.append((nr, nc))
            result.append(comp)
        return result

    lower = components(1, divider + 1, h)[0]
    indicator = components(2, 0, divider)[0]
    color = next(grid[r][c] for r in range(divider) for c in range(w)
                 if grid[r][c] not in (0, 1, 2, 5))
    colored = components(color, 0, divider)[0]

    out = [[0] * w for _ in range(out_h)]
    lower_top = min(r for r, c in lower) - divider - 1
    lower_bottom = max(r for r, c in lower) - divider - 1
    lower_left = min(c for r, c in lower)

    for r, c in lower:
        out[r - divider - 1][c] = 1

    # The colored shape is placed opposite the wide end of the 2-marker.
    row_widths = {}
    for r, c in indicator:
        row_widths[r] = row_widths.get(r, 0) + 1
    widest_row = max(row_widths, key=row_widths.get)
    colored_above = widest_row > (min(r for r, c in indicator) +
                                   max(r for r, c in indicator)) / 2

    color_top = min(r for r, c in colored)
    color_bottom = max(r for r, c in colored)
    color_left = min(c for r, c in colored)
    color_height = color_bottom - color_top + 1

    if colored_above:
        dest_top = lower_top - color_height
    else:
        dest_top = lower_bottom + 1

    for r, c in colored:
        nr = dest_top + (r - color_top)
        nc = lower_left + (c - color_left)
        if 0 <= nr < out_h and 0 <= nc < w:
            out[nr][nc] = color

    return out
